content:
:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --bg-gradient: linear-gradient(135deg, #1e1e2f 0%, #161622 100%);
  --card-bg: rgba(30, 32, 48, 0.75);
  --card-border: rgba(255, 255, 255, 0.08);
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;

  --primary-color: #ef4444;
  --primary-hover: #dc2626;
  --primary-glow: rgba(239, 68, 68, 0.25);

  --secondary-color: #3b82f6;
  --secondary-hover: #2563eb;

  --circle-bg: rgba(255, 255, 255, 0.05);
  --circle-stroke: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  -webkit-font-smoothing: antialiased;
}

.pomodoro-app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.timer-card {
  width: 100%;
  background: var(--card-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  padding: 32px 24px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
}

.mode-tabs {
  display: flex;
  background: rgba(0, 0, 0, 0.25);
  padding: 4px;
  border-radius: 9999px;
  gap: 4px;
  width: 100%;
  max-width: 360px;
}

.mode-tab {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-weight: 600;
  padding: 8px 12px;
  border-radius: 9999px;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.mode-tab:hover {
  color: #ffffff;
}

.mode-tab.active {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.timer-display-container {
  position: relative;
  width: 260px;
  height: 260px;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 8px 0;
}

.timer-svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.timer-circle-bg {
  stroke: var(--circle-bg);
  fill: transparent;
  stroke-width: 8px;
}

.timer-circle-progress {
  stroke: var(--circle-stroke);
  fill: transparent;
  stroke-width: 8px;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.5s ease, stroke 0.3s ease;
  filter: drop-shadow(0 0 6px var(--primary-glow));
}

.timer-text-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  pointer-events: none;
}

.timer-time {
  font-size: 3.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.04em;
  color: #ffffff;
  line-height: 1;
}

.timer-status-text {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-top: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.controls-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  width: 100%;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
  user-select: none;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: var(--primary-color);
  color: #ffffff;
  min-width: 140px;
  box-shadow: 0 4px 14px var(--primary-glow);
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
  min-width: 140px;
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.16);
}

.btn-reset {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  padding: 12px;
  border-radius: 12px;
}

.btn-reset:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.stats-container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 4px;
}

.stat-badge {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  padding: 8px 16px;
  font-size: 0.875rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-count {
  font-weight: 700;
  color: #ffffff;
  font-variant-numeric: tabular-nums;
}

.notification-message {
  font-size: 0.875rem;
  color: #34d399;
  background: rgba(52, 211, 153, 0.1);
  border: 1px solid rgba(52, 211, 153, 0.2);
  padding: 8px 16px;
  border-radius: 8px;
  text-align: center;
  width: 100%;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 480px) {
  .timer-card {
    padding: 24px 16px;
  }

  .timer-display-container {
    width: 220px;
    height: 220px;
  }

  .timer-time {
    font-size: 3rem;
  }

  .btn {
    padding: 10px 18px;
  }
}

export type TimerMode = 'work' | 'shortBreak' | 'longBreak';

export interface TimerDisplayProps {
  mode: TimerMode;
  timeLeft: number;
  totalTime: number;
  isRunning: boolean;
}

export interface TimerControlsProps {
  isRunning: boolean;
  currentMode: TimerMode;
  onStart: () => void;
  onPause: () => void;
  onReset: () => void;
  onChangeMode: (mode: TimerMode) => void;
}

export interface PomodoroSettings {
  work: number;
  shortBreak: number;
  longBreak: number;
}

import { FC } from 'react';
import { TimerDisplayProps } from '../types';

const TimerDisplay: FC<TimerDisplayProps> = ({
  mode,
  timeLeft,
  totalTime,
  isRunning,
}) => {
  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  const radius = 105;
  const circumference = 2 * Math.PI * radius;
  const safeTotal = totalTime > 0 ? totalTime : 1;
  const progressRatio = Math.max(0, Math.min(1, timeLeft / safeTotal));
  const strokeDashoffset = circumference * (1 - progressRatio);

  const getStatusText = () => {
    if (!isRunning && timeLeft === totalTime) {
      if (mode === 'work') return '作業準備中';
      if (mode === 'shortBreak') return '小休憩準備中';
      return '長休憩準備中';
    }
    if (!isRunning) {
      return '一時停止中';
    }
    if (mode === 'work') return '集中タイム';
    if (mode === 'shortBreak') return '短い休憩中';
    return '長い休憩中';
  };

  const getProgressColor = () => {
    if (mode === 'work') return '#ef4444';
    if (mode === 'shortBreak') return '#10b981';
    return '#3b82f6';
  };

  return (
    <div className="timer-display-container">
      <svg className="timer-svg" viewBox="0 0 240 240">
        <circle
          className="timer-circle-bg"
          cx="120"
          cy="120"
          r={radius}
        />
        <circle
          className="timer-circle-progress"
          cx="120"
          cy="120"
          r={radius}
          style={{
            strokeDasharray: circumference,
            strokeDashoffset,
            stroke: getProgressColor(),
          }}
        />
      </svg>
      <div className="timer-text-overlay">
        <div className="timer-time">{formattedTime}</div>
        <div className="timer-status-text">{getStatusText()}</div>
      </div>
    </div>
  );
};

export default TimerDisplay;

import { FC } from 'react';
import { TimerControlsProps, TimerMode } from '../types';

const TimerControls: FC<TimerControlsProps> = ({
  isRunning,
  currentMode,
  onStart,
  onPause,
  onReset,
  onChangeMode,
}) => {
  const modes: { id: TimerMode; label: string }[] = [
    { id: 'work', label: '作業 (25分)' },
    { id: 'shortBreak', label: '短い休憩 (5分)' },
    { id: 'longBreak', label: '長い休憩 (15分)' },
  ];

  return (
    <>
      <div className="mode-tabs">
        {modes.map((m) => {
          const tabClassName = currentMode === m.id ? 'mode-tab active' : 'mode-tab';
          return (
            <button
              key={m.id}
              type="button"
              className={tabClassName}
              onClick={() => onChangeMode(m.id)}
            >
              {m.label}
            </button>
          );
        })}
      </div>

      <div className="controls-container">
        {isRunning ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={onPause}
          >
            一時停止
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-primary"
            onClick={onStart}
          >
            スタート
          </button>
        )}
        <button
          type="button"
          className="btn btn-reset"
          onClick={onReset}
          title="タイマーをリセット"
        >
          リセット
        </button>
      </div>
    </>
  );
};

export default TimerControls;

import { useState, useEffect, useRef, FC } from 'react';
import TimerDisplay from './components/TimerDisplay';
import TimerControls from './components/TimerControls';
import { TimerMode, PomodoroSettings } from './types';
import './index.css';

const DEFAULT_SETTINGS: PomodoroSettings = {
  work: 25 * 60,
  shortBreak: 5 * 60,
  longBreak: 15 * 60,
};

const playCompletionSound = () => {
  try {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioContextClass) return;

    const ctx = new AudioContextClass();
    const now = ctx.currentTime;

    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((freq, index) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now + index * 0.12);

      gain.gain.setValueAtTime(0, now + index * 0.12);
      gain.gain.linearRampToValueAtTime(0.2, now + index * 0.12 + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, now + index * 0.12 + 0.35);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now + index * 0.12);
      osc.stop(now + index * 0.12 + 0.36);
    });
  } catch {
    // ユーザー操作制限等によるオーディオ失敗時は何もしない
  }
};

const App: FC = () => {
  const [currentMode, setCurrentMode] = useState<TimerMode>('work');
  const [timeLeft, setTimeLeft] = useState<number>(DEFAULT_SETTINGS.work);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [completedSessions, setCompletedSessions] = useState<number>(0);
  const [notification, setNotification] = useState<string | null>(null);

  const notificationTimeoutRef = useRef<number | null>(null);

  const totalTime = DEFAULT_SETTINGS[currentMode];

  const showNotification = (msg: string) => {
    if (notificationTimeoutRef.current) {
      window.clearTimeout(notificationTimeoutRef.current);
    }
    setNotification(msg);
    notificationTimeoutRef.current = window.setTimeout(() => {
      setNotification(null);
    }, 5000);
  };

  useEffect(() => {
    let interval: number | null = null;

    if (isRunning) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            playCompletionSound();
            setIsRunning(false);

            if (currentMode === 'work') {
              setCompletedSessions((c) => c + 1);
              showNotification('作業セッションが完了しました！よく頑張りました。休憩を取りましょう。');
            } else {
              showNotification('休憩時間が終了しました！次の作業を始めましょう。');
            }

            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isRunning, currentMode]);

  useEffect(() => {
    return () => {
      if (notificationTimeoutRef.current) {
        window.clearTimeout(notificationTimeoutRef.current);
      }
    };
  }, []);

  const handleStart = () => {
    if (timeLeft === 0) {
      setTimeLeft(DEFAULT_SETTINGS[currentMode]);
    }
    setIsRunning(true);
  };

  const handlePause = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(DEFAULT_SETTINGS[currentMode]);
  };

  const handleChangeMode = (mode: TimerMode) => {
    if (mode === currentMode) return;
    setIsRunning(false);
    setCurrentMode(mode);
    setTimeLeft(DEFAULT_SETTINGS[mode]);
  };

  return (
    <main className="pomodoro-app">
      <div className="timer-card">
        <h1 className="header-title">
          <span>🍅</span> ポモドーロタイマー
        </h1>

        <TimerControls
          isRunning={isRunning}
          currentMode={currentMode}
          onStart={handleStart}
          onPause={handlePause}
          onReset={handleReset}
          onChangeMode={handleChangeMode}
        />

        <TimerDisplay
          mode={currentMode}
          timeLeft={timeLeft}
          totalTime={totalTime}
          isRunning={isRunning}
        />

        {notification && (
          <div className="notification-message">
            {notification}
          </div>
        )}

        <div className="stats-container">
          <div className="stat-badge">
            <span>完了セッション:</span>
            <span className="stat-count">{completedSessions} 回</span>
          </div>
        </div>
      </div>
    </main>
  );
};

export default App;
